"""``foxglove-wizard`` entry point driving the quickstart: auth -> stream a recording -> upload."""

from __future__ import annotations

import argparse
import os
import tempfile
import time
import uuid
from concurrent.futures import Future, ThreadPoolExecutor
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from enum import Enum
from importlib import metadata, resources
from typing import NoReturn, Optional
from urllib.parse import urlparse

from . import ui
from .api import ApiError, FoxgloveClient
from .auth import AuthError, authenticate
from .mcap_copy import remux_mcap
from .player import compute_now_anchor, play

DEFAULT_MCAP_PATH = str(resources.files("foxglove_wizard").joinpath("drone.mcap"))

DEFAULT_API_URL = "https://api.foxglove.dev"
DEFAULT_APP_URL = "https://app.foxglove.dev"

CLIENT_ID = "foxglove-wizard"

DEVICE_NAME = "onboarding-quickstart-drone"

_QUICKSTART_LAYOUT_IDS = {
    "prod": "lay_0eWDIgnrTdpIdpyi",
    "party": "lay_0eUG4YCJxCgGmPsf",
}


def _quickstart_layout_id(api_url: str) -> str | None:
    """Resolve the quickstart layout id from the api-url's environment, or None."""
    hostname = (urlparse(api_url).hostname or "").lower()
    if hostname.endswith("foxglove.party") or hostname.endswith("foxglove-app-party.pages.dev"):
        return _QUICKSTART_LAYOUT_IDS["party"]
    if hostname.endswith("foxglove.dev"):
        return _QUICKSTART_LAYOUT_IDS["prod"]
    return None

# Poll GET /v1/recordings/{key} until the async import pipeline reports the recording available.
_RECORDING_POLL_INTERVAL_S = 2.0
_RECORDING_POLL_TIMEOUT_S = 60.0


def _version() -> str:
    try:
        return metadata.version("foxglove-wizard")
    except metadata.PackageNotFoundError:
        return "unknown"


def _upload_filename() -> str:
    """Timestamped upload filename"""
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    return f"onboarding_drone_{stamp}.mcap"


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="foxglove-wizard",
        description="Stream an existing MCAP recording live into Foxglove and "
        "upload it.",
    )
    parser.add_argument(
        "--api-url",
        default=os.environ.get("FOXGLOVE_API_URL", DEFAULT_API_URL),
        help=f"Foxglove API base URL (default: {DEFAULT_API_URL})",
    )
    parser.add_argument(
        "--app-url",
        default=os.environ.get("FOXGLOVE_APP_URL")
    )
    parser.add_argument(
        "--project-id",
        default=os.environ.get("FOXGLOVE_PROJECT_ID"),
        help="Target project id (required, or set FOXGLOVE_PROJECT_ID).",
    )
    parser.add_argument(
        "--mcap",
        default=DEFAULT_MCAP_PATH,
        help="Input MCAP recording to stream and upload.",
    )
    return parser


def _fail(message: str) -> NoReturn:
    """Print a concise error and exit non-zero."""
    ui.error(message)
    raise SystemExit(1)


def _wait_for_exit() -> None:
    """Hold the live connection open until the user presses Enter."""
    print()
    ui.info("Foxglove is still connected. Press Enter to exit.")
    try:
        input()
    except (EOFError, KeyboardInterrupt):
        pass
    ui.info("Closing the connection.")


def _recording_url(
    app_url: str | None,
    org_slug: str | None,
    project_id: str | None,
    key: str,
) -> str | None:
    if not org_slug:
        return None
    app_base = (app_url or DEFAULT_APP_URL).rstrip("/")
    if project_id:
        return f"{app_base}/{org_slug}/p/{project_id}/recordings/{key}/general"
    return f"{app_base}/{org_slug}/recordings/{key}/general"


@dataclass(frozen=True)
class _UploadResult:
    """What the report step needs to verify and link to the uploaded recording."""

    url: str | None
    key: str


def _upload_recording(
    *,
    api_url: str,
    bearer: str,
    mcap_path: str,
    project_id: str | None,
    app_url: str | None,
    org_slug: str | None,
) -> _UploadResult:
    key = uuid.uuid4().hex
    offset_ns, takeoff_at = compute_now_anchor(mcap_path)
    upload_fd, upload_path = tempfile.mkstemp(suffix=".mcap")
    os.close(upload_fd)
    try:
        remux_mcap(mcap_path, upload_path, nonce=key, time_offset_ns=offset_ns)
        with FoxgloveClient(api_url, bearer) as client:
            client.upload_mcap(
                upload_path,
                device_name=DEVICE_NAME,
                project_id=project_id,
                filename=_upload_filename(),
                key=key,
            )
            client.create_event(
                device_name=DEVICE_NAME,
                start=takeoff_at,
                end=takeoff_at + timedelta(seconds=1),
                metadata={"event": "takeoff"},
                project_id=project_id,
            )
    finally:
        try:
            os.remove(upload_path)
        except OSError:  # temp cleanup is best-effort
            pass
    return _UploadResult(url=_recording_url(app_url, org_slug, project_id, key), key=key)


class _RecordingStatus(Enum):
    AVAILABLE = "available"
    FAILED = "failed"
    TIMED_OUT = "timed_out"


def _poll_recording_available(client: FoxgloveClient, key: str) -> _RecordingStatus:
    """Poll for the recording, returning its terminal import status."""
    deadline = time.monotonic() + _RECORDING_POLL_TIMEOUT_S
    print("Verifying your recording is available in Foxglove", end="", flush=True)
    while time.monotonic() < deadline:
        try:
            recording = client.get_recording(key)
        except Exception:  # a transient error just means "not ready yet"
            recording = None
        if recording is not None:
            status = recording.get("importStatus")
            if status == "complete":
                print()
                return _RecordingStatus.AVAILABLE
            if status == "failed":
                print()
                return _RecordingStatus.FAILED
        time.sleep(_RECORDING_POLL_INTERVAL_S)
        print(".", end="", flush=True)
    print()
    return _RecordingStatus.TIMED_OUT


def _report_upload(
    upload_future: "Future[_UploadResult]",
    *,
    api_url: str,
    bearer: str,
) -> None:
    """Join the background upload, poll for availability, and report the outcome."""
    try:
        upload = upload_future.result()
    except ApiError as err:
        ui.error(f"Upload failed: {err}")
        return
    except Exception as err:  # surface the reason, keep the stream alive
        ui.error(f"Upload failed: {err}")
        return

    with FoxgloveClient(api_url, bearer) as client:
        outcome = _poll_recording_available(client, upload.key)

    if outcome == _RecordingStatus.AVAILABLE:
        ui.success("Uploaded.")
        print()
        ui.success("All done! Your recording has been uploaded to Foxglove.")
        if upload.url is not None:
            ui.info("View your recording in Foxglove:")
            ui.link(upload.url)
        else:
            ui.info("Open the Recordings page in Foxglove to see your recording.")
    elif outcome == _RecordingStatus.FAILED:
        ui.error("Recording import failed. Check the recording in Foxglove.")
    else:
        ui.warn("Your recording is still importing. It will appear here shortly:")
        if upload.url is not None:
            ui.link(upload.url)


def _run() -> None:
    args = _build_parser().parse_args()
    ui.banner("Welcome to the Foxglove quickstart guide")
    ui.detail(f"foxglove-wizard v{_version()}")
    ui.info(
        "This guide will set up a live streaming connection and upload a recording into Foxglove."
    )

    total_steps = 3
    step_number = 0

    project_id = args.project_id
    if project_id is None:
        _fail("--project-id is required (or set FOXGLOVE_PROJECT_ID).")

    step_number += 1
    ui.step(step_number, total_steps, "Sign in to Foxglove")
    bearer = authenticate(
        args.api_url,
        CLIENT_ID,
        open_browser=True,
        app_url=args.app_url,
    )
    ui.success("Signed in.")

    # Resolve the org slug so the live-view link can target the project-scoped route.
    org_slug: Optional[str] = None
    with FoxgloveClient(args.api_url, bearer) as client:
        try:
            org_slug = client.org_slug()
        except ApiError:
            org_slug = None

    # Upload in a background thread
    executor = ThreadPoolExecutor(max_workers=1)
    upload_future: Future[_UploadResult] = executor.submit(
        _upload_recording,
        api_url=args.api_url,
        bearer=bearer,
        mcap_path=args.mcap,
        project_id=project_id,
        app_url=args.app_url,
        org_slug=org_slug,
    )

    step_number += 1
    ui.step(step_number, total_steps, "Stream your recording")
    playback = play(
        args.mcap,
        view_base_url=args.app_url or DEFAULT_APP_URL,
        layout_id=_quickstart_layout_id(args.api_url),
        org_slug=org_slug,
        project_id=project_id,
        wait_for_subscriber=True,
    )

    try:
        # Only surface the upload step once a viewer has actually connected.
        if playback.connected:
            step_number += 1
            ui.step(step_number, total_steps, "Upload your recording")
            ui.info("Uploading recording…")
            _report_upload(upload_future, api_url=args.api_url, bearer=bearer)

        _wait_for_exit()
    finally:
        executor.shutdown(wait=True)
        playback.stop()


def main() -> None:
    """Entry point: run the wizard, surfacing only a concise message on failure."""
    try:
        _run()
    except KeyboardInterrupt:
        print()
        ui.warn("Cancelled.")
        raise SystemExit(130)
    except (AuthError, ApiError) as err:
        ui.error(str(err))
        raise SystemExit(1)
    except Exception as err:  # surface the reason, not a traceback
        ui.error(str(err))
        raise SystemExit(1)
